// hubfam keys for features/learninghub/quiz/** and QuestionsPanel.tsx (all keys prefixed `qz`).
// Authored as rows: r(key, en, pl, ro, ur, pa, bn, ar, pt, es, fr, cy). x(key, {locale: text}) adds extra CLDR plural forms
// (zero/two/few/many) for the locales that need them; base `_one`/`_other` rows exist for every locale.
// Question CONTENT is never translated; only chrome. {placeholders} are kept intact.
const LOCS = ["en", "pl", "ro", "ur", "pa", "bn", "ar", "pt", "es", "fr", "cy"] as const;
const part: Record<string, Record<string, string>> = { en: {}, pl: {}, ro: {}, ur: {}, pa: {}, bn: {}, ar: {}, pt: {}, es: {}, fr: {}, cy: {} };
const r = (key: string, ...v: string[]) => { if (v.length !== LOCS.length) throw new Error(`hubfam quiz row ${key}: expected ${LOCS.length} texts, got ${v.length}`); LOCS.forEach((l, i) => { part[l]![key] = v[i]!; }); };
const x = (key: string, forms: Partial<Record<(typeof LOCS)[number], string>>) => { for (const [l, s] of Object.entries(forms)) part[l]![key] = s!; };

// ── plural families ──
